Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <queue>
#include <stack>
#include <set>
#include <map>
#include <unordered_map>
#include <algorithm>
#include <cmath>
#include <cstring>
#include <climits>
#include <cassert>
using namespace std;

int n, T;
vector<string> gridA, gridB;
int distFromStart[30][30], distToFinish[30][30];
int dirsX[4] = {0, 0, -1, 1};
int dirsY[4] = {1, -1, 0, 0};

struct FlowEdge {
    int u, v, capacity, flow;
    FlowEdge(int a, int b, int cap) : u(a), v(b), capacity(cap), flow(0) {}
};

vector<vector<int>> graph;
vector<FlowEdge> edges;
vector<int> level, curPtr;
int source, sink;

void addEdge(int u, int v, int cap) {
    edges.push_back(FlowEdge(u, v, cap));
    edges.push_back(FlowEdge(v, u, 0));
    graph[u].push_back(edges.size() - 2);
    graph[v].push_back(edges.size() - 1);
}

bool bfs_level() {
    fill(level.begin(), level.end(), -1);
    queue<int> q;
    q.push(source);
    level[source] = 0;
    while (!q.empty() && level[sink] == -1) {
        int u = q.front(); q.pop();
        for (int id : graph[u]) {
            auto &e = edges[id];
            if (level[e.v] == -1 && e.flow < e.capacity) {
                level[e.v] = level[u] + 1;
                q.push(e.v);
            }
        }
    }
    return level[sink] != -1;
}

int dfs_block(int u, int flow) {
    if (u == sink || flow == 0) return flow;
    for (int &i = curPtr[u]; i < (int)graph[u].size(); ++i) {
        int id = graph[u][i];
        auto &e = edges[id];
        if (level[e.v] != level[u] + 1) continue;
        int pushed = dfs_block(e.v, min(flow, e.capacity - e.flow));
        if (pushed > 0) {
            e.flow += pushed;
            edges[id^1].flow -= pushed;
            return pushed;
        }
    }
    return 0;
}

int max_flow() {
    int total = 0;
    while (bfs_level()) {
        fill(curPtr.begin(), curPtr.end(), 0);
        while (int pushed = dfs_block(source, INT_MAX)) {
            total += pushed;
        }
    }
    return total;
}

bool inside(int x, int y) {
    return x >= 0 && x < n && y >= 0 && y < n;
}

void computeDist1(int sx, int sy) {
    for (int i = 0; i < 30; ++i)
        for (int j = 0; j < 30; ++j)
            distFromStart[i][j] = INT_MAX;
    queue<pair<int,int>> q;
    q.push({sx, sy});
    distFromStart[sx][sy] = 0;
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + dirsX[d], ny = y + dirsY[d];
            if (inside(nx, ny) && distFromStart[nx][ny] == INT_MAX && gridB[nx][ny] != 'Y') {
                distFromStart[nx][ny] = distFromStart[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
}

void computeDist2(int sx, int sy) {
    for (int i = 0; i < 30; ++i)
        for (int j = 0; j < 30; ++j)
            distToFinish[i][j] = INT_MAX;
    queue<pair<int,int>> q;
    q.push({sx, sy});
    distToFinish[sx][sy] = 0;
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        if (distToFinish[x][y] >= distFromStart[x][y]) continue;
        for (int d = 0; d < 4; ++d) {
            int nx = x + dirsX[d], ny = y + dirsY[d];
            if (inside(nx, ny) && distToFinish[nx][ny] == INT_MAX && gridA[nx][ny] != 'Y' && distToFinish[x][y] + 1 <= distFromStart[nx][ny]) {
                distToFinish[nx][ny] = distToFinish[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> T;
    gridA.resize(n); gridB.resize(n);
    for (int i = 0; i < n; ++i) cin >> gridA[i];
    for (int i = 0; i < n; ++i) cin >> gridB[i];

    int zx = -1, zy = -1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (gridB[i][j] == 'Z') {
                gridA[i][j] = gridB[i][j] = 'Y';
                zx = i; zy = j;
            }
        }
    }

    computeDist1(zx, zy);

    int nodes = 2 * n * n + 2;
    graph.assign(nodes, vector<int>());
    level.assign(nodes, 0);
    curPtr.assign(nodes, 0);
    source = 0; sink = nodes - 1;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (gridA[i][j] == 'Y') continue;
            int u = i * n + j + 1;
            int v = n * n + u;
            int cap1 = gridA[i][j] - '0';
            int cap2 = gridB[i][j] - '0';
            addEdge(source, u, cap1);
            addEdge(v, sink, cap2);
            computeDist2(i, j);
            for (int x = 0; x < n; ++x) {
                for (int y = 0; y < n; ++y) {
                    if (gridB[x][y] == 'Y' || distToFinish[x][y] > T) continue;
                    addEdge(u, n * n + x * n + y + 1, cap1);
                }
            }
        }
    }

    cout << max_flow() << "\n";
    return 0;
}
